":1,"location":{"latitude":64.1456,"longitude":-21.9284},"opening_hours":"Mo-Th 17:00-00:00; Fr-Sa 15:00-01:00; Su 17:00-00:00","google_maps_url":"https://www.google.com/maps/search/Vínstúkan+Tíu+Sopar+Reykjavik","website":"tiu-sopar.is","phone":"547 2380","best_of_award":"Best Wine Bar 2025 + 2026 — Reykjavík Grapevine","grapevine_url":"https://grapevine.is/best-of-reykjavik/2026/02/24/best-of-reykjavik-2026-best-wine-bar-2/","image":null},"g4u5dfiawy":{"_type":"venue","name":"Bodega","address":"Austurstræti 22","description":"Best outdoor seating in town. Heaters, blankets, and cozy vibes year-round. Prime people-watching territory.","note":"Wednesday: all-day Martinis. Thursday: all-day sparkling wine.","time":"6:30 PM","is_free":1,"location":{"latitude":64.1474,"longitude":-21.9397},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Bodega+bar+Austurstræti+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"tlvt7nuzt8":{"_type":"venue","name":"Daisy Cocktail Bar","address":"Ingólfsstræti 8","description":"One of Reykjavík''s best cocktail bars, tucked into a semi-basement. Intimate, low-lit, great energy. Bartenders know exactly what they''re doing.","note":null,"time":"8:00 PM","is_free":0,"location":{"latitude":64.1476,"longitude":-21.9362},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Daisy+Cocktail+Bar+Ingólfsstræti+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"zd6xfknx7m":{"_type":"venue","name":"12 Tónar / The Irishman Pub","address":"Skólavörðustígur 15 / Austurstræti 20","description":"Your palate cleanser. 12 Tónar: cozy, creative, always full of locals with great beers and live music. The Irishman: loud, lively, full of energy. Choose your vibe.","note":null,"time":"9:30 PM","is_free":0,"location":{"latitude":64.1462,"longitude":-21.9338},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/12+Tónar+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"22d1eb6clq":{"_type":"venue","name":"Röntgen","address":"Hverfisgata 12","description":"This is where the party kicks in. Late-night dancing, good drinks, reliably cool DJ lineup. The energy builds as the night goes on.","note":"The disco ball doesn''t spin itself. And if you cut your fingers, they''ve got band-aids at the bar.","time":"11:30 PM","is_free":0,"location":{"latitude":64.1471,"longitude":-21.933},"opening_hours":"Mo 18-00; Tu-We 16-01; Th 14-01; Fr-Sa 14-03; Su 18-00","google_maps_url":"https://www.google.com/maps/search/Röntgen+bar+Hverfisgata+Reykjavik","website":"rontgenbar.is","phone":"691 9662","best_of_award":"Best Goddamn Bar 2026 — Reykjavík Grapevine","grapevine_url":"https://grapevine.is/best-of-reykjavik/2026/02/24/best-of-reykjavik-2026-best-goddamn-bar/","image":null},"h3lgaen4rv":{"_type":"venue","name":"Kaffibarinn","address":"Bergstaðastræti 1","description":"Gritty, loud, packed, and an absolute Reykjavík institution. This is where nights end or spiral. No judgment. Just vibes.","note":null,"time":"Bonus — Sometime in the AM","is_free":0,"location":{"latitude":64.1458,"longitude":-21.9349},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Kaffibarinn+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null}}}}}}}','2026-03-21T18:14:12.646Z','2026-03-21T18:14:13.780Z','admin','admin','admin',NULL,NULL,'Reykjavík Bar Crawl','bar-crawl','February 2026','A walkable evening route through Reykjavík’s best pubs, cocktail bars, and late-night spots. With drink tips and timing.',5,'Nh29BBzZgbR9j_zbd7G6gQ==','https://rvkfoodie.gumroad.com/l/barcrawl','https://www.google.com/maps/placelists/list/bar-crawl-reykjavik','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"A curated route through the bars worth your time in Reykjavík — all walkable, with suggested timing so you don’t peak too early. Drink tips, local favourites, and a Google Maps pin list included."}]}]}}','{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"r6l3y3jdhl"}]}}');
INSERT INTO "content_guide" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","subtitle","description","price","gumroad_product_id","gumroad_url","google_maps_url","intro","content") VALUES('nw9rviesmj','published','2026-03-21T18:14:17.919Z','2026-03-21T18:14:17.919Z','{"title":"Golden Circle Food Guide","slug":"golden-circle","subtitle":"Updated in 2026","description":"The best food stops along Iceland’s Golden Circle. From greenhouse dining to proper hot dogs to coastal langoustine.","price":12,"gumroad_product_id":"tQ2p0Rc-AOTIB9MbCgUAug==","gumroad_url":"https://rvkfoodie.gumroad.com/l/goldencircle","google_maps_url":"https://www.google.com/maps/placelists/list/golden-circle-food-stops","intro":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"The Golden Circle is Iceland’s most popular route — but most people eat badly while driving it. This guide is a short list of places actually worth stopping for."}]},{"type":"paragraph","children":[{"type":"span","value":"Greenhouse dining, geothermal soaking with a serious restaurant attached, proper Icelandic hot dogs in Selfoss, and langoustine on the coast — planned around the drive so you’re not scrambling."}]},{"type":"heading","level":3,"children":[{"type":"span","value":"Each spot includes"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What to order"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What they’re known for"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Location and opening hours"}]}]}]}]}},"blocks":{}},"content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"jgxxkfja6q"},{"type":"block","item":"q9rp90vjj8"}]}},"blocks":{"jgxxkfja6q":{"_type":"section","title":"Along the Route","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"oxa3s8sjdo"},{"type":"block","item":"o2mswg3hdo"},{"type":"block","item":"rokxit4yp6"},{"type":"block","item":"losf48ed3r"},{"type":"block","item":"6xzuaggitr"},{"type":"block","item":"g77t1n6dtn"},{"type":"block","item":"z001l3hyu3"},{"type":"block","item":"2uv02q57eb"},{"type":"block","item":"524oq3drkj"}]}},"blocks":{"oxa3s8sjdo":{"_type":"venue","name":"Matkráin","address":"Hvergardi","description":"Cozy, modern restaurant. Seasonal Icelandic ingredients, creative dishes that feel elevated without being stiff. Worth planning around.","note":"Just 40 minutes from Reykjavík.","time":null,"is_free":1,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"o2mswg3hdo":{"_type":"venue","name":"GK Bakarí","address":"Selfoss","description":"A proper Icelandic bakery. Flaky pastries, cinnamon rolls, and traditional cakes. Great for breakfast on the road.","note":null,"time":null,"is_free":1,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"rokxit4yp6":{"_type":"venue","name":"Friðheimar","address":"Reykholt, just off the Golden Circle route","description":"Dining inside a working tomato greenhouse. Unlimited tomato soup and freshly baked bread. Don''t skip the burrata or tomato beer. A must-stop.","note":null,"time":null,"is_free":1,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"losf48ed3r":{"_type":"venue","name":"Vínstofa Friðheima","address":"Reykholt (next to Friðheimar)","description":"Quieter than the greenhouse next door. Good wines, small plates.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"6xzuaggitr":{"_type":"venue","name":"Laugarás Lagoon + Ylja Restaurant","address":"Laugarás (between Selfoss and Geysir)","description":"New geothermal lagoon with a proper restaurant attached. Chef Gísli Matt (formerly Dill) runs the kitchen. Worth building your day around.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"g77t1n6dtn":{"_type":"venue","name":"Pylsuvagninn","address":"Selfoss town center","description":"Classic Icelandic hot dog stand. Order it með öllu (with everything). Quick, cheap, and very Icelandic.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"z001l3hyu3":{"_type":"venue","name":"Rauða Húsið","address":"Eyrarbakki (coastal detour from Selfoss)","description":"Historic red house in a fishing village. Known for the lobster soup — it’s earned the reputation. Good for a longer stop.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"2uv02q57eb":{"_type":"venue","name":"Flúðasveppir","address":"Flúðir","description":"Local mushroom farm serving lunch. Rich mushroom soup, hearty dishes. Low-key and local.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"524oq3drkj":{"_type":"venue","name":"Tommi''s Burger Joint","address":"Selfoss","description":"Old-school, no-nonsense burgers. Simple, affordable, consistently good. Classic cheeseburger with fries and a milkshake.","note":null,"time":null,"is_free":0,"location":null,"opening_hours":null,"google_maps_url":null,"website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null}}}},"q9rp90vjj8":{"_type":"text_block","heading":"RVKFOODIE Tip","is_free":1,"content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Do not try to do all of this in one rushed Golden Circle day. Plan one sit-down experience and balance it with one casual stop. The Golden Circle is about pace — eat well, soak somewhere, and enjoy the drive."}]},{"type":"paragraph","children":[{"type":"span","value":"Food is part of the experience — not just a pit stop.","marks":["strong"]}]}]}},"blocks":{}}}}}}','2026-03-21T18:14:13.939Z','2026-03-21T18:14:17.919Z','admin','admin','admin',NULL,NULL,'Golden Circle Food Guide','golden-circle','Updated in 2026','The best food stops along Iceland’s Golden Circle. From greenhouse dining to proper hot dogs to coastal langoustine.',12,'tQ2p0Rc-AOTIB9MbCgUAug==','https://rvkfoodie.gumroad.com/l/goldencircle','https://www.google.com/maps/placelists/list/golden-circle-food-stops','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"The Golden Circle is Iceland’s most popular route — but most people eat badly while driving it. This guide is a short list of places actually worth stopping for."}]},{"type":"paragraph","children":[{"type":"span","value":"Greenhouse dining, geothermal soaking with a serious restaurant attached, proper Icelandic hot dogs in Selfoss, and langoustine on the coast — planned around the drive so you’re not scrambling."}]},{"type":"heading","level":3,"children":[{"type":"span","value":"Each spot includes"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What to order"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What they’re known for"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Location and opening hours"}]}]}]}]}}','{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"jgxxkfja6q"},{"type":"block","item":"q9rp90vjj8"}]}}');
INSERT INTO "content_guide" ("id","_status","_published_at","_first_published_at","_published_snapshot","_created_at","_updated_at","_created_by","_updated_by","_published_by","_scheduled_publish_at","_scheduled_unpublish_at","title","slug","subtitle","description","price","gumroad_product_id","gumroad_url","google_maps_url","intro","content") VALUES('7guc0nxad6','published','2026-03-24T17:15:47.869Z','2026-03-21T18:14:19.536Z','{"title":"Reykjavík with Kids","slug":"reykjavik-with-kids","subtitle":"Where to eat when you''ve got little ones in tow","description":"A local parent''s guide to eating out with kids in Reykjavík. Play areas, high chairs, patient staff, and food that makes everyone happy — including you. Updated for 2026.","price":10,"gumroad_product_id":"reykjavik-with-kids","gumroad_url":"https://rvkfoodie.gumroad.com/l/reykjavik-with-kids","google_maps_url":"https://www.google.com/maps/placelists/list/reykjavik-kids-food","intro":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Reykjavík is surprisingly great for eating out with kids — if you know where to go. This guide is for parents who want to eat well without sacrificing their sanity or settling for chicken nuggets.","marks":["strong"]}]},{"type":"heading","level":3,"children":[{"type":"span","value":"Why this guide"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Written by a local parent who eats out constantly — every place here has been tested with actual children"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Honest notes on high chairs, pram space, play areas, and changing facilities"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What to order for picky eaters AND what the parents should get"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Timing tips — when to go to avoid the chaos"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"No tourist traps, no chain restaurants — just places locals actually bring their families"}]}]}]},{"type":"heading","level":3,"children":[{"type":"span","value":"What’s inside"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"15 spots across breakfast, lunch, dinner, and dessert"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Practical parent intel you won’t find on any review site"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Google Maps pin list for easy navigation with a car seat in tow"}]}]}]}]}},"blocks":{}},"content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"s1"},{"type":"block","item":"s2"},{"type":"block","item":"s3"},{"type":"block","item":"s4"},{"type":"block","item":"t1"}]}},"blocks":{"s1":{"_type":"section","title":"Breakfast & Brunch","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"v1"},{"type":"block","item":"v2"},{"type":"block","item":"v3"}]}},"blocks":{"v1":{"_type":"venue","name":"Sandholt Bakery","address":"Laugavegur 36","description":"Kids eat free here — that alone earns it a spot. But it’s also just a lovely bakery. Sourdough, flaky pastries, and a cozy sit-in area. Grab a cinnamon roll for the toddler and a proper coffee for yourself. Mornings are calm before 9AM; after that it gets busy.","note":"Kids eat free. Highchairs available.","time":null,"is_free":1,"location":{"latitude":64.145,"longitude":-21.926},"opening_hours":"Mo-Su 07:30-18:00","google_maps_url":"https://www.google.com/maps/search/Sandholt+Laugavegur+36+Reykjavik","website":null,"phone":null,"best_of_award":"Best Bakery 2025 — Reykjavík Grapevine","grapevine_url":null,"image":null},"v2":{"_type":"venue","name":"Laundromat Café","address":"Austurstræti 9","description":"The secret weapon: a basement play area filled with toys, books, and pillows. Drop the kids down there and enjoy your brunch in relative peace. Weekend brunch has pancakes, eggs, bacon, and fruit smoothies. Board games for the older ones.","note":"Basement play area. Weekend brunch Sat-Sun 09:00-15:00.","time":null,"is_free":1,"location":{"latitude":64.1474,"longitude":-21.9387},"opening_hours":"Mo-Su 08:00-23:00","google_maps_url":"https://www.google.com/maps/search/Laundromat+Café+Austurstræti+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"v3":{"_type":"venue","name":"Brauð & Co","address":"Frakkastígur 16","description":"Opens at 6:30AM for the early risers (or the parents who had no choice). Cinnamon buns the size of your toddler’s head. Pretzel croissants that keep little hands busy. Quick in-and-out — perfect for grabbing pastries before a walk around the pond.","note":"Takeaway-friendly. No real seating for lingering with kids.","time":null,"is_free":0,"location":{"latitude":64.144,"longitude":-21.9261},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Brau%C3%B0+Co+Frakkast%C3%ADgur+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null}}}},"s2":{"_type":"section","title":"Lunch","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"v4"},{"type":"block","item":"v5"},{"type":"block","item":"v6"},{"type":"block","item":"v7"},{"type":"block","item":"v8"}]}},"blocks":{"v4":{"_type":"venue","name":"Le Kock","address":"Tryggvagata 14","description":"Sister restaurant to DEIG, and one of the most naturally family-friendly spots downtown. Legendary burgers in DEIG-made potato brioche buns. The space is relaxed, the staff are patient, and the food is genuinely good.","note":"Highchairs available. Spacious enough for prams.","time":null,"is_free":0,"location":{"latitude":64.1501,"longitude":-21.9434},"opening_hours":"Mo-Su 11:30-22:00","google_maps_url":"https://www.google.com/maps/search/Le+Kock+Tryggvagata+Reykjavik","website":"lekock.is","phone":null,"best_of_award":null,"grapevine_url":null,"image":"td5cucw0c5"},"v5":{"_type":"venue","name":"Kaffi Lækur","address":"Laugarnesvegur 75","description":"A neighbourhood gem popular with new parents. Dedicated kids’ corner with toys and books. Sourdough flatbakes are hearty and delicious. Slightly off the tourist path.","note":"Kids’ corner with toys and books.","time":null,"is_free":0,"location":{"latitude":64.1422,"longitude":-21.9058},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/Kaffi+L%C3%A6kur+Laugarnesvegur+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"v6":{"_type":"venue","name":"Chickpea","address":"Hallveigastígur 1","description":"Family-run vegetarian spot with the best falafel in town. Generous portions, freshly made, warm and unhurried vibe. Great for kids who like wraps and hummus.","note":"Vegetarian/vegan. Casual and quick.","time":null,"is_free":0,"location":{"latitude":64.1457,"longitude":-21.9341},"opening_hours":"Mo-Su 10:00-20:00","google_maps_url":"https://www.google.com/maps/search/Chickpea+Reykjavik","website":"chickpea.is","phone":null,"best_of_award":null,"grapevine_url":null,"image":"e59v159sv3"},"v7":{"_type":"venue","name":"La Poblana","address":"Laugavegur 12, 2nd floor","description":"Authentic Mexican food on the second floor of Laugavegur 12. Family-run, using recipes from Puebla. Way more than just tacos — enchiladas in salsa verde, quesadillas, burritos, and plenty of other dishes. Everything is customisable and most items work great as kid food: small portions, handheld, easy to share. Vegetarian and gluten-free options if your little one has restrictions. Warm, unhurried vibe.","note":"Family-run. Full Mexican menu beyond tacos. Vegetarian, vegan and gluten-free options.","time":null,"is_free":0,"location":{"latitude":64.1468,"longitude":-21.9308},"opening_hours":"Su-Th 12:00-21:00; Fr-Sa 12:00-21:00","google_maps_url":"https://www.google.com/maps/search/La+Poblana+Laugavegur+Reykjavik","website":"lapoblana.is","phone":"760 7221","best_of_award":null,"grapevine_url":null,"image":"nkpti6fxvu"},"v8":{"_type":"venue","name":"Plantan Bistro (Norræna húsið)","address":"Sturlugata 5","description":"Plant-based bistro inside the Nordic House — an Alvar Aalto-designed cultural gem. Come for lunch, stay for the library. The kids’ section has children’s literature in Nordic languages, a play area, and storytelling hours in winter. Free library card. Perfect rainy-day combo: eat, read, explore.","note":"Nordic House library with dedicated kids’ section, play area, and storytelling hours. Open Tue–Sun.","time":null,"is_free":0,"location":{"latitude":64.142,"longitude":-21.9508},"opening_hours":"Mo-Su 11:00-17:00","google_maps_url":"https://www.google.com/maps/search/Plantan+Bistro+Norraena+husid+Reykjavik","website":"plantankaffihus.is","phone":"551 7030","best_of_award":null,"grapevine_url":null,"image":null}}}},"s3":{"_type":"section","title":"Dinner","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"v9"},{"type":"block","item":"v10"},{"type":"block","item":"v11"},{"type":"block","item":"v12"}]}},"blocks":{"v9":{"_type":"venue","name":"Búllan","address":"Geirsgata 1","description":"Multiple locations around town, but the Geirsgata spot by the old harbour is the one most visitors will hit first. No-frills burgers, zero pretension, walls covered in kids’ drawings — your kids can add to the collection. The Höfði branch (Bolholt 6) is perfect if you’re on your way out of town.","note":"Multiple locations. Geirsgata for downtown, Höfði (Bolholt 6) on the way out of town.","time":null,"is_free":0,"location":{"latitude":64.1512,"longitude":-21.9443},"opening_hours":null,"google_maps_url":"https://www.google.com/maps/search/B%C3%BAllan+Geirsgata+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":"t6gzo781k7"},"v10":{"_type":"venue","name":"Jómfrúin","address":"Lækjargata 4","description":"Classic Danish smørrebrød — open-faced sandwiches perfect for kids who like to pick and choose toppings. Best service in town means they’ll be patient with your order taking twice as long.","note":"Best service in town. Patient with families.","time":null,"is_free":0,"location":{"latitude":64.1468,"longitude":-21.9374},"opening_hours":"Mo-Su 11:30-22:00","google_maps_url":"https://www.google.com/maps/search/J%C3%B3mfr%C3%BAin+L%C3%A6kjargata+Reykjavik","website":null,"phone":"551 0100","best_of_award":null,"grapevine_url":null,"image":"qzs1eqbdl3"},"v11":{"_type":"venue","name":"2guys","address":"Laugavegur 105 (Hlemmur)","description":"Award-winning burgers at Hlemmur — voted Best Burger in Reykjavík four years running. They have a proper kids’ menu: Klemma burger, fries and juice for 1,500 ISK. The vibe is relaxed enough that nobody bats an eye at a messy eater. Great veggie options too.","note":"Kids’ menu available (1,500 ISK). Best Burger 2023–2026.","time":null,"is_free":0,"location":{"latitude":64.1428,"longitude":-21.9148},"opening_hours":"Mo-Su 11:30-21:00","google_maps_url":"https://www.google.com/maps/search/2guys+Laugavegur+105+Reykjavik","website":"2guys.is","phone":"790 2323","best_of_award":null,"grapevine_url":null,"image":null},"v12":{"_type":"venue","name":"Just Wing’in It","address":"Snorrabraut 56","description":"Over 30 wing flavours plus chicken tenders for the less adventurous. The real draw for kids: corn hole tossing and shuffleboard to keep them busy while you eat. Casual, loud, zero judgement — basically designed for families even if they didn’t mean to be.","note":"Games for kids (corn hole, shuffleboard). Takeaway available.","time":null,"is_free":0,"location":{"latitude":64.143,"longitude":-21.915},"opening_hours":"Mo-Su 11:30-21:00","google_maps_url":"https://www.google.com/maps/search/Just+Wingin+It+Snorrabraut+Reykjavik","website":"justwinginit.is","phone":"661 2878","best_of_award":null,"grapevine_url":null,"image":null}}}},"s4":{"_type":"section","title":"Sweet Treats & Ice Cream","venues":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"v13"},{"type":"block","item":"v14"},{"type":"block","item":"v15"}]}},"blocks":{"v13":{"_type":"venue","name":"DEIG Workshop","address":"Tryggvagata 14","description":"Doughnuts and bagels made fresh daily. The doughnuts are the obvious kid-magnet, but don’t sleep on the bagels. Perfect post-playground bribe.","note":"Right next to Le Kock — easy to combine visits.","time":null,"is_free":0,"location":{"latitude":64.1501,"longitude":-21.9434},"opening_hours":"Mo-Fr 07:00-17:00; Sa-Su 08:00-16:00","google_maps_url":"https://www.google.com/maps/search/DEIG+Workshop+Tryggvagata+Reykjavik","website":null,"phone":null,"best_of_award":null,"grapevine_url":null,"image":null},"v14":{"_type":"venue","name":"Mokka Kaffi","address":"Skólavörðustígur 3a","description":"Open since 1958 and barely changed since — red carpet, leatherette booths, rotating art on the walls. The waffles with cream and jam are the reason you’re here. Kids love them, you’ll love the espresso (Mokka was the first café in Iceland to serve it). A Reykjavík institution.","note":"Open since 1958. Famous waffles with cream and jam.","time":null,"is_free":0,"location":{"latitude":64.1441,"longitude":-21.9278},"opening_hours":"Mo-Su 09:00-18:00","google_maps_url":"https://www.google.com/maps/search/Mokka+Kaffi+Sk%C3%B3lav%C3%B6r%C3%B0ust%C3%ADgur+Reykjavik","website":"mokka.is","phone":"552 1174","best_of_award":null,"grapevine_url":null,"image":null},"v15":{"_type":"venue","name":"Gaeta Gelato","address":"Aðalstræti 6 (Ingólfstorg)","description":"Proper Italian gelato made fresh daily on Ingólfstorg. Pistachio, salted caramel, and seasonal flavours — plus cannoli and tiramisu if the kids want to branch out. The owners have nearly 25 years of experience as gelato makers. Open late, perfect for a post-dinner stroll.","note":"Fresh gelato daily. Open until 23:00.","time":null,"is_free":0,"location":{"latitude":64.1477,"longitude":-21.9399},"opening_hours":"Mo-Su 12:30-23:00","google_maps_url":"https://www.google.com/maps/search/Gaeta+Gelato+Ingolfstorg+Reykjavik","website":"gelato.is","phone":null,"best_of_award":null,"grapevine_url":null,"image":null}}}},"t1":{"_type":"text_block","heading":"Tips for Eating Out with Kids in Reykjavík","is_free":1,"content":{"value":{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Icelanders eat late.","marks":["strong"]},{"type":"span","value":" Dinner service starts at 17:00–18:00. If you go right when doors open, you’ll often have the place to yourself."}]},{"type":"paragraph","children":[{"type":"span","value":"Most places have highchairs.","marks":["strong"]},{"type":"span","value":" But they’re often the basic IKEA kind. If your child needs a specific setup, bring your own clip-on seat."}]},{"type":"paragraph","children":[{"type":"span","value":"Changing tables are rare.","marks":["strong"]},{"type":"span","value":" Outside of the bigger restaurants and shopping centres, you’ll mostly be improvising."}]},{"type":"paragraph","children":[{"type":"span","value":"Don’t stress about the kids.","marks":["strong"]},{"type":"span","value":" Reykjavík is extremely child-friendly as a culture. Nobody’s going to glare at you if your toddler is being a toddler."}]},{"type":"paragraph","children":[{"type":"span","value":"Book ahead for dinner.","marks":["strong"]},{"type":"span","value":" The best places are small. Mentioning you’re bringing kids when you book helps them seat you somewhere with more space."}]}]}},"blocks":{}}}}}}','2026-03-21T18:14:18.090Z','2026-03-24T17:15:47.869Z','admin','Sunna','Sunna',NULL,NULL,'Reykjavík with Kids','reykjavik-with-kids','Where to eat when you''ve got little ones in tow','A local parent''s guide to eating out with kids in Reykjavík. Play areas, high chairs, patient staff, and food that makes everyone happy — including you. Updated for 2026.',10,'reykjavik-with-kids','https://rvkfoodie.gumroad.com/l/reykjavik-with-kids','https://www.google.com/maps/placelists/list/reykjavik-kids-food','{"schema":"dast","document":{"type":"root","children":[{"type":"paragraph","children":[{"type":"span","value":"Reykjavík is surprisingly great for eating out with kids — if you know where to go. This guide is for parents who want to eat well without sacrificing their sanity or settling for chicken nuggets.","marks":["strong"]}]},{"type":"heading","level":3,"children":[{"type":"span","value":"Why this guide"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Written by a local parent who eats out constantly — every place here has been tested with actual children"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Honest notes on high chairs, pram space, play areas, and changing facilities"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"What to order for picky eaters AND what the parents should get"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Timing tips — when to go to avoid the chaos"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"No tourist traps, no chain restaurants — just places locals actually bring their families"}]}]}]},{"type":"heading","level":3,"children":[{"type":"span","value":"What’s inside"}]},{"type":"list","style":"bulleted","children":[{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"15 spots across breakfast, lunch, dinner, and dessert"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Practical parent intel you won’t find on any review site"}]}]},{"type":"listItem","children":[{"type":"paragraph","children":[{"type":"span","value":"Google Maps pin list for easy navigation with a car seat in tow"}]}]}]}]}}','{"schema":"dast","document":{"type":"root","children":[{"type":"block","item":"s1"},{"type":"block","item":"s2"},{"type":"block","item":"s3"},{"type":"block","item":"s4"},{"type":"block","item":"t1"}]}}');
